insert into _kba24(node_id, blocks, search_text) values
(80, $kba24b_80$[{"t":"list","id":"a2-2-4-1-b1","imp":"core","title":"","ordered":false,"items":["1、算法","（1）==程序=算法+数据结构==","（2）==算法是指解决问题的一种方法或一个过程==。是若干指令的有穷序列。","（3）算法的设计一般采用由粗到细、由抽象到具体的逐步求精的方法。","（4）==算法的必要满足条件（有些教材称为五大特性，最后一条拆为==@@无输入@@==和==@@至少一输出@@==）：==","==①、确定性：算法的每一条指令必须有确切的定义，无二义性。==","==②、有穷性：是指算法必须在有限的时间内做完，即算法必须能在执行有限个步骤之后终止。==","==③、可行性：算法中的描述在计算机中能执行，且在有穷时间内完成。==","==④、至少有一个（1 个或多个）输出，但是可以没有（0 个或多个）输入==","（5）算法的组成要素：一个算法由==数据对象的运算和操作以及其==@@控制结构@@这两部分组成。","（6）算法的基本运算和操作：==算术运算，逻辑运算，关系运算，数据传输等==。","（7）算法的基本控制结构包含：==顺序结构、选择结构、循环结构。==","（7）算法的基本设计方法：列举法、归纳法、递推、递归、减半递推技术。","2、^^算法与程序的区别^^","^^（1）算法是解决问题的方法、步骤^^","^^（2）程序是算法的具体代码实现^^","^^（3）算法是程序设计的核心，算法的好坏直接决定了程序的效率^^","^^（4）程序中的语句必须是机器可执行的，算法中的操作无此限制。^^","^^（5）算法与程序是相应的，但不是一一对应。^^","3、==算法的表示（描述工具）==","==（1）自然语言：算法可以用自然语言来描述，缺点是不够准确。==","==（2）流程图==","==（3）程序设计语言==","==（4）伪代码（PDL）：介于自然语言和程序设计语言之间的文字和符号表达工具。==","4、==评价算法的优劣应考虑的主要因素（算法的分析）==","==算法分析==是指对一个算法的运行时间和占用空间做定量的分析，一般计算出相应的数量级，常用时间复杂度和空间复杂度表示。==分析算法的目的就是要降低算法的时间复杂度和空间复杂度，提高算法的执行效率。==","（1）==算法的复杂度==：时间复杂度和空间复杂度","（2）==正确性==:算法的正确性是评价一个算法优劣的最重要的标准。","（3）==可读性（易理解）==:算法的可读性是指一个算法可供人们阅读的容易程度，算法是否容易理解。","（4）==健壮性==:健壮性是指一个算法对不合理数据输入的反应能力和处理能力，也称为容错性。","5、==算法的复杂度==","（1）算法的复杂度：算法效率的度量","（2）算法复杂度分类：==时间复杂度和空间复杂度==","①、==时间复杂度：指执行算法所需要的计算工作量。==通常，一个算法所用的时间包括编译时间和运行时间。度量方法是执行算法所需要的基本运算次数。","②、==空间复杂度：指执行这个算法所需要的内存空间。==包括算法程序所占的空间，输入的初始数据所占的空间，算法执行过程中所需的额外空间。","（3）==空间复杂度和时间复杂度并不相关。==","（4）查找算法最坏比较次数","==①、顺序查找：只能用顺序查找的情况，线性无序表；有序线性链表。==","==长度为 n 的线性表最坏查找次数为：n 次；==","==最大值或最小值的比较次数为 n-1 次==","==②、二分法查找：==二分法只适用于==顺序存储的有序表。==最坏比较次数为：log₂n 次。","查找算法的复杂度表"]},{"h":341,"t":"img","w":1350,"id":"a2-2-4-1-b2","imp":"normal","src":"/kb-assets/theory/p37_r0_05f91a89d4420795.png","title":""},{"t":"list","id":"a2-2-4-1-b3","imp":"normal","items":["（5）排序算法最坏比较次数"],"title":"","ordered":false},{"h":427,"t":"img","w":414,"id":"a2-2-4-1-b4","imp":"normal","src":"/kb-assets/theory/p37_r1_2ebee42b2484246a.png","title":""},{"t":"list","id":"a2-2-4-1-b5","imp":"normal","items":["排序算复杂度表"],"title":"","ordered":false},{"h":478,"t":"img","w":1337,"id":"a2-2-4-1-b6","imp":"normal","src":"/kb-assets/theory/p38_r0_f5cb273f3a1ed243.png","title":""},{"t":"list","id":"a2-2-4-1-b7","imp":"core","title":"","ordered":false,"items":["6、^^算法的概念与基本要求^^：算法就是计算机解题的过程。在计算机学科中，算法指的是==用于完成某个信息处理任务的有序而明确的、可以由计算机执行的一组操作（或指令）==，它能在有限时间内执行结束并产生结果。同一个问题可以设计不同的算法来解决。瑞士计算机科学家尼克劳斯·沃思（Niklaus Wirth）关于“算法”提出过两个著名论述：","① ==数据结构 + 算法 = 程序==；","② ==计算机科学就是研究算法的学问==。","7、^^算法选择与算法分析^^：一般而言，算法的选择除了考虑其正确性以外，还应考虑以下因素：","① 执行算法所要占用计算机资源的多少，包括==时间资源和空间资源==两个方面。^^如果一个算法所编制的程序要反复运行多次，则应重点考虑时间代价；若待解决问题的数据量较大，则应重点考虑空间代价。^^","② 算法是否容易理解，是否容易调试和测试等。","8、^^常见的数据挖掘算法^^：","① ==C4.5、CART==：决策树算法","② ==朴素贝叶斯（NB）==","③ ==支持向量机（SVM）==","9、^^算法设计与分析的三方面问题^^：关于算法，需要考虑以下三个方面的问题：==如何确定算法（算法设计）、如何表示算法（算法表示）以及如何使算法更有效（算法的复杂性分析）==。","10、^^空间效率与算法特性^^：","（1）==空间效率（空间代价）==：相对量度，包括^^程序本身所占空间、数据所占空间、运行所占内存空间^^。计算机中处处是算法，算法是计算机的灵魂；算法解决一类问题，不是一个问题。沃思：==程序 = 算法 + 数据结构==。","（2）^^算法的特性^^：==确定性==（无二义）；==能行性/可行性==（每一步都必须在计算机能力范围内）；==有穷性==（执行有限步骤后必须结束）；==输出性==（至少一个输出）。@@根据算法写出的程序有可能会出现无穷（由计算机计算局限性造成）@@。"]},{"t":"callout","id":"a2-2-4-1-b8","imp":"core","kind":"tip","title":"考向复习提示：算法核心特征与时间/空间复杂度","text":"算法是指解题方案的准确完整描述，必须具备五大特征：==有穷性（有限步终止）、确定性（无二义性）、可行性（可执行）、输入（0 个或多个）、输出（至少 1 个）==。评价算法效率采用==时间复杂度（基本运算执行次数关于规模 n 的数量级）==与==空间复杂度（所需额外/总内存空间，两者互不相关）==。"},{"t":"callout","id":"a2-2-4-1-b9","imp":"core","kind":"trap","title":"高频易错陷阱：0 输入必须有输出 & 二分查找前提与运行时间误区","text":"（1）==算法可以有 0 个输入，但必须至少有 1 个输出！==“程序可以是无穷的，算法必须是有穷的”。（2）==二分法查找只适用于顺序存储的有序表==（链式存储不可二分），最坏比较次数简记为 `log₂n`（严格上界为 `⌊log₂n⌋ + 1`）；^^时间复杂度不是程序实际运行的绝对秒数^^！"}]$kba24b_80$::jsonb, $kba24s_80$A2-2.4.1 算法的基本概念，算法复杂度的概念和意义（时间复杂度与空间复杂度）。 1、算法 （1）程序=算法+数据结构 （2）算法是指解决问题的一种方法或一个过程。是若干指令的有穷序列。 （3）算法的设计一般采用由粗到细、由抽象到具体的逐步求精的方法。 （4）算法的必要满足条件（有些教材称为五大特性，最后一条拆为无输入和至少一输出）： ①、确定性：算法的每一条指令必须有确切的定义，无二义性。 ②、有穷性：是指算法必须在有限的时间内做完，即算法必须能在执行有限个步骤之后终止。 ③、可行性：算法中的描述在计算机中能执行，且在有穷时间内完成。 ④、至少有一个（1 个或多个）输出，但是可以没有（0 个或多个）输入 （5）算法的组成要素：一个算法由数据对象的运算和操作以及其控制结构这两部分组成。 （6）算法的基本运算和操作：算术运算，逻辑运算，关系运算，数据传输等。 （7）算法的基本控制结构包含：顺序结构、选择结构、循环结构。 （7）算法的基本设计方法：列举法、归纳法、递推、递归、减半递推技术。 2、算法与程序的区别 （1）算法是解决问题的方法、步骤 （2）程序是算法的具体代码实现 （3）算法是程序设计的核心，算法的好坏直接决定了程序的效率 （4）程序中的语句必须是机器可执行的，算法中的操作无此限制。 （5）算法与程序是相应的，但不是一一对应。 3、算法的表示（描述工具） （1）自然语言：算法可以用自然语言来描述，缺点是不够准确。 （2）流程图 （3）程序设计语言 （4）伪代码（PDL）：介于自然语言和程序设计语言之间的文字和符号表达工具。 4、评价算法的优劣应考虑的主要因素（算法的分析） 算法分析是指对一个算法的运行时间和占用空间做定量的分析，一般计算出相应的数量级，常用时间复杂度和空间复杂度表示。分析算法的目的就是要降低算法的时间复杂度和空间复杂度，提高算法的执行效率。 （1）算法的复杂度：时间复杂度和空间复杂度 （2）正确性:算法的正确性是评价一个算法优劣的最重要的标准。 （3）可读性（易理解）:算法的可读性是指一个算法可供人们阅读的容易程度，算法是否容易理解。 （4）健壮性:健壮性是指一个算法对不合理数据输入的反应能力和处理能力，也称为容错性。 5、算法的复杂度 （1）算法的复杂度：算法效率的度量 （2）算法复杂度分类：时间复杂度和空间复杂度 ①、时间复杂度：指执行算法所需要的计算工作量。通常，一个算法所用的时间包括编译时间和运行时间。度量方法是执行算法所需要的基本运算次数。 ②、空间复杂度：指执行这个算法所需要的内存空间。包括算法程序所占的空间，输入的初始数据所占的空间，算法执行过程中所需的额外空间。 （3）空间复杂度和时间复杂度并不相关。 （4）查找算法最坏比较次数 ①、顺序查找：只能用顺序查找的情况，线性无序表；有序线性链表。 长度为 n 的线性表最坏查找次数为：n 次； 最大值或最小值的比较次数为 n-1 次 ②、二分法查找：二分法只适用于顺序存储的有序表。最坏比较次数为：log₂n 次。 查找算法的复杂度表 （5）排序算法最坏比较次数 排序算复杂度表 6、算法的概念与基本要求：算法就是计算机解题的过程。在计算机学科中，算法指的是用于完成某个信息处理任务的有序而明确的、可以由计算机执行的一组操作（或指令），它能在有限时间内执行结束并产生结果。同一个问题可以设计不同的算法来解决。瑞士计算机科学家尼克劳斯·沃思（Niklaus Wirth）关于“算法”提出过两个著名论述： ① 数据结构 + 算法 = 程序； ② 计算机科学就是研究算法的学问。 7、算法选择与算法分析：一般而言，算法的选择除了考虑其正确性以外，还应考虑以下因素： ① 执行算法所要占用计算机资源的多少，包括时间资源和空间资源两个方面。如果一个算法所编制的程序要反复运行多次，则应重点考虑时间代价；若待解决问题的数据量较大，则应重点考虑空间代价。 ② 算法是否容易理解，是否容易调试和测试等。 8、常见的数据挖掘算法： ① C4.5、CART：决策树算法 ② 朴素贝叶斯（NB） ③ 支持向量机（SVM） 9、算法设计与分析的三方面问题：关于算法，需要考虑以下三个方面的问题：如何确定算法（算法设计）、如何表示算法（算法表示）以及如何使算法更有效（算法的复杂性分析）。 10、空间效率与算法特性： （1）空间效率（空间代价）：相对量度，包括程序本身所占空间、数据所占空间、运行所占内存空间。计算机中处处是算法，算法是计算机的灵魂；算法解决一类问题，不是一个问题。沃思：程序 = 算法 + 数据结构。 （2）算法的特性：确定性（无二义）；能行性/可行性（每一步都必须在计算机能力范围内）；有穷性（执行有限步骤后必须结束）；输出性（至少一个输出）。根据算法写出的程序有可能会出现无穷（由计算机计算局限性造成）。 考向复习提示：算法核心特征与时间/空间复杂度 算法是指解题方案的准确完整描述，必须具备五大特征：有穷性（有限步终止）、确定性（无二义性）、可行性（可执行）、输入（0 个或多个）、输出（至少 1 个）。评价算法效率采用时间复杂度（基本运算执行次数关于规模 n 的数量级）与空间复杂度（所需额外/总内存空间，两者互不相关）。 高频易错陷阱：0 输入必须有输出 & 二分查找前提与运行时间误区 （1）算法可以有 0 个输入，但必须至少有 1 个输出！“程序可以是无穷的，算法必须是有穷的”。（2）二分法查找只适用于顺序存储的有序表（链式存储不可二分），最坏比较次数简记为 `log₂n`（严格上界为 `⌊log₂n⌋ + 1`）；时间复杂度不是程序实际运行的绝对秒数！$kba24s_80$),
(81, $kba24b_81$[{"t":"list","id":"a2-2-4-2-b1","imp":"core","title":"","ordered":false,"items":["1、数据结构基本概念","（1）数据：数据是客观事物的符号表示，是能输入到计算机中并被计算程序识别和处理的符号的总称，如文档，声音，视频等。","（2）数据元素：数据元素是数据的基本单位。","（3）数据对象：数据对象是性质相同的数据元素的集合。","（4）==数据结构：是指由某一数据对象中所有数据成员之间的关系组成的集合。==","（5）研究数据结构一般包括三方面：==数据的逻辑结构、数据的存储结构，定义在逻辑结构和存储结构上的运算。==","2、数据结构的逻辑结构","（1）==数据的逻辑结构是对数据元素之间的逻辑关系的描述，与数据的存储无关，是面向问题的，是独立于计算机的。它包括数据对象和数据对象之间的关系。==","要素：D, R；D 为数据元素的集合，R 是 D 上关系的集合","D={父亲，儿子，女儿}，R={{父亲，儿子}，{父亲，女儿}}","（2）常见的逻辑结构："]},{"t":"img","id":"a2-2-4-2-b2","imp":"normal","src":"/kb-assets/theory/p38_r1_362cff7813db915b.png","w":1362,"h":290,"title":""},{"t":"list","id":"a2-2-4-2-b3","imp":"core","title":"","ordered":false,"items":["==① 集合结构∶数据中的元素同属于一个集合。==","==② 线性表结构∶数据元素按先后次序连接。==","==③ 树形结构∶数据元素间存在一对多的关系。==","==④ 网状结构∶数据元素有各种各样的复杂连接，数据元素间存在多对多的关系。==","3、数据结构的物理结构","（1）==数据的存储结构也称为数据的物理结构，是数据在计算机中的存放的方式，是面向计算机的，它包括数据元素的存储方式和关系的存储方式。==","（2）==常见的存储结构：顺序，链式，索引等==","4、数据结构","（1）图形表示：","①、数据元素表示：用矩形方框（□）表示一个数据元素。","②、R 关系的二元组：一条有向线段（→）从前件指向后件","1）没有前件的结点称为“==根结点==”","2）没有后件的结点称为“==叶子结点==”","3）除了根结点和叶子结点的其他结点称为“内部结点”"]},{"t":"img","id":"a2-2-4-2-b4","imp":"normal","src":"/kb-assets/theory/p39_r0_6f6366941eb6d4f8.png","w":490,"h":362,"title":""},{"t":"list","id":"a2-2-4-2-b5","imp":"core","title":"","ordered":false,"items":["（2）==线性结构：栈、队列、双向链表等==","==①、有且只有一个根结点==","==②、每个结点最多有一个前件，也最多有一个后件=="]},{"t":"img","id":"a2-2-4-2-b6","imp":"normal","src":"/kb-assets/theory/p39_r1_4c79b7e55f8aecdd.png","w":1350,"h":114,"title":""},{"t":"list","id":"a2-2-4-2-b7","imp":"core","title":"","ordered":false,"items":["（3）==非线性结构：不满足线性结构条件的数据结构。如树、二叉树为非线性结构。=="]},{"t":"img","id":"a2-2-4-2-b8","imp":"normal","src":"/kb-assets/theory/p39_r2_f7a3729dde09d59b.png","w":553,"h":310,"title":""},{"t":"list","id":"a2-2-4-2-b9","imp":"core","title":"","ordered":false,"items":["5、^^两种基本存储结构要点（顺序与链式）^^：","① ==顺序存储==：==元素存储在连续的物理空间中==。若元素大小为 1B，从内存 0# 地址开始则元素下标即地址码；若元素大小为 L B，则第 i 个元素的地址为：==元素首地址 + i×L==。^^顺序存储只存数据不存指针，容易随机存取，但不容易插入和删除。^^","② ==链式存储==：每个结点不仅有数据（值域），还有体现逻辑关系的^^指针域^^。各结点存储位置可以不连续，^^存储密度小于顺序存储^^，但^^很容易进行插入与删除^^，常用于动态变化的数据结构。","6、^^数据结构的三要素与基本结论^^：数据结构包括三方面内容：==数据的逻辑结构、数据的存储结构和定义在该结构上的运算==。","^^① 逻辑结构分为线性结构和非线性结构^^：==线性结构==包括一般线性表以及栈、队列、数组、双向链表等；==非线性结构==包括集合、树形结构（一般树、二叉树）和图形结构（有向图、无向图）。","^^② 存储结构分为顺序存储和链式存储^^：@@任何一个逻辑结构在计算机中都可以采用这两种方式存储@@；数据的运算包括查找、排序、插入、删除、修改等。","7、^^数据的物理结构（存储结构）补充^^：数据逻辑结构在计算机中的存放方式称为物理结构，常见有==顺序、链式、索引、散列==四种：","① ==顺序存储结构==：把逻辑上相邻的元素存储在物理位置也相邻的存储单元里，一般称为@@紧凑存储结构@@，主要应用于线性数据结构。","② ==链式存储结构==：不要求物理位置相邻，结点间逻辑关系用附加的指针域表示，适用于线性结构和非线性结构。","8、^^数据结构的三方面内容与实现方式^^：","（1）逻辑结构包含四种典型关系：集合结构（同属一个集合，如一篮子鸡蛋）、线性结构（一对一先后顺序，如窗口排队）、树结构（一对多层次关系，如家谱）、图或网状结构（多对多任意关系）。","（2）逻辑结构的内存实现：^^顺序实现^^（支持随机访问，不适合频繁插删）与^^链接表实现^^（适合插删；尾指针可为 NULL，或全部非空形成环路）。","9、^^常用的数据结构与两种存储结构的比较^^：","① ==易于扩充空间==：^^链接结构好^^，顺序结构一般；","② ==插入、删除运算==：^^链接结构好^^，顺序结构一般；","③ ==是否占用连续存储空间==：==链接结构否==，==顺序结构是==；","④ ==存储空间效率（存储密度）==：^^链接结构较低（含指针开销）^^，==顺序结构较高（无指针开销）==；","⑤ ==随机存取能力==：==顺序结构支持 O(1) 随机访问==，链接结构需从头顺序查找。","10、^^数据结构的研究内容小结^^：① ==数据的逻辑结构==：抽象反映数据元素之间的约束关系，与存储方式无关；② ==数据的物理存储结构==：逻辑结构在计算机存储器上的映象/实现（包括元素自身的值与元素间关系）；③ ==数据的运算==：定义在结构上的操作集合。"]},{"t":"callout","id":"a2-2-4-2-b10","imp":"core","kind":"tip","title":"考向复习提示：数据结构三要素与逻辑/物理存储区分","text":"数据结构三要素为：==逻辑结构（面向问题：集合、线性、树形、图状）==、==物理/存储结构（面向计算机：顺序、链式、索引、散列）==以及==数据的运算==；同一逻辑结构可对应多种存储结构，==数据处理的效率直接受所选存储结构影响==。"},{"t":"callout","id":"a2-2-4-2-b11","imp":"core","kind":"trap","title":"高频易错陷阱：逻辑结构判定与双向链表/循环队列归类","text":"专转本高频判断题陷阱：==逻辑结构只看元素间的前驱与后继个数关系==！^^“有且只有一个根结点、每个结点最多一个前件和一个后件”即线性结构^^——因此==一般线性表、栈、队列、循环队列、单链表、双向链表、循环链表均属于线性结构==！而与采用的存储结构（顺序还是链式）毫无关系！"}]$kba24b_81$::jsonb, $kba24s_81$A2-2.4.2 数据结构的定义，数据的逻辑结构与存储结构，数据结构的图形表示，线性结构与非线性结构的概念。 1、数据结构基本概念 （1）数据：数据是客观事物的符号表示，是能输入到计算机中并被计算程序识别和处理的符号的总称，如文档，声音，视频等。 （2）数据元素：数据元素是数据的基本单位。 （3）数据对象：数据对象是性质相同的数据元素的集合。 （4）数据结构：是指由某一数据对象中所有数据成员之间的关系组成的集合。 （5）研究数据结构一般包括三方面：数据的逻辑结构、数据的存储结构，定义在逻辑结构和存储结构上的运算。 2、数据结构的逻辑结构 （1）数据的逻辑结构是对数据元素之间的逻辑关系的描述，与数据的存储无关，是面向问题的，是独立于计算机的。它包括数据对象和数据对象之间的关系。 要素：D, R；D 为数据元素的集合，R 是 D 上关系的集合 D={父亲，儿子，女儿}，R={{父亲，儿子}，{父亲，女儿}} （2）常见的逻辑结构： ① 集合结构∶数据中的元素同属于一个集合。 ② 线性表结构∶数据元素按先后次序连接。 ③ 树形结构∶数据元素间存在一对多的关系。 ④ 网状结构∶数据元素有各种各样的复杂连接，数据元素间存在多对多的关系。 3、数据结构的物理结构 （1）数据的存储结构也称为数据的物理结构，是数据在计算机中的存放的方式，是面向计算机的，它包括数据元素的存储方式和关系的存储方式。 （2）常见的存储结构：顺序，链式，索引等 4、数据结构 （1）图形表示： ①、数据元素表示：用矩形方框（□）表示一个数据元素。 ②、R 关系的二元组：一条有向线段（→）从前件指向后件 1）没有前件的结点称为“根结点” 2）没有后件的结点称为“叶子结点” 3）除了根结点和叶子结点的其他结点称为“内部结点” （2）线性结构：栈、队列、双向链表等 ①、有且只有一个根结点 ②、每个结点最多有一个前件，也最多有一个后件 （3）非线性结构：不满足线性结构条件的数据结构。如树、二叉树为非线性结构。 5、两种基本存储结构要点（顺序与链式）： ① 顺序存储：元素存储在连续的物理空间中。若元素大小为 1B，从内存 0# 地址开始则元素下标即地址码；若元素大小为 L B，则第 i 个元素的地址为：元素首地址 + i×L。顺序存储只存数据不存指针，容易随机存取，但不容易插入和删除。 ② 链式存储：每个结点不仅有数据（值域），还有体现逻辑关系的指针域。各结点存储位置可以不连续，存储密度小于顺序存储，但很容易进行插入与删除，常用于动态变化的数据结构。 6、数据结构的三要素与基本结论：数据结构包括三方面内容：数据的逻辑结构、数据的存储结构和定义在该结构上的运算。 ① 逻辑结构分为线性结构和非线性结构：线性结构包括一般线性表以及栈、队列、数组、双向链表等；非线性结构包括集合、树形结构（一般树、二叉树）和图形结构（有向图、无向图）。 ② 存储结构分为顺序存储和链式存储：任何一个逻辑结构在计算机中都可以采用这两种方式存储；数据的运算包括查找、排序、插入、删除、修改等。 7、数据的物理结构（存储结构）补充：数据逻辑结构在计算机中的存放方式称为物理结构，常见有顺序、链式、索引、散列四种： ① 顺序存储结构：把逻辑上相邻的元素存储在物理位置也相邻的存储单元里，一般称为紧凑存储结构，主要应用于线性数据结构。 ② 链式存储结构：不要求物理位置相邻，结点间逻辑关系用附加的指针域表示，适用于线性结构和非线性结构。 8、数据结构的三方面内容与实现方式： （1）逻辑结构包含四种典型关系：集合结构（同属一个集合，如一篮子鸡蛋）、线性结构（一对一先后顺序，如窗口排队）、树结构（一对多层次关系，如家谱）、图或网状结构（多对多任意关系）。 （2）逻辑结构的内存实现：顺序实现（支持随机访问，不适合频繁插删）与链接表实现（适合插删；尾指针可为 NULL，或全部非空形成环路）。 9、常用的数据结构与两种存储结构的比较： ① 易于扩充空间：链接结构好，顺序结构一般； ② 插入、删除运算：链接结构好，顺序结构一般； ③ 是否占用连续存储空间：链接结构否，顺序结构是； ④ 存储空间效率（存储密度）：链接结构较低（含指针开销），顺序结构较高（无指针开销）； ⑤ 随机存取能力：顺序结构支持 O(1) 随机访问，链接结构需从头顺序查找。 10、数据结构的研究内容小结：① 数据的逻辑结构：抽象反映数据元素之间的约束关系，与存储方式无关；② 数据的物理存储结构：逻辑结构在计算机存储器上的映象/实现（包括元素自身的值与元素间关系）；③ 数据的运算：定义在结构上的操作集合。 考向复习提示：数据结构三要素与逻辑/物理存储区分 数据结构三要素为：逻辑结构（面向问题：集合、线性、树形、图状）、物理/存储结构（面向计算机：顺序、链式、索引、散列）以及数据的运算；同一逻辑结构可对应多种存储结构，数据处理的效率直接受所选存储结构影响。 高频易错陷阱：逻辑结构判定与双向链表/循环队列归类 专转本高频判断题陷阱：逻辑结构只看元素间的前驱与后继个数关系！“有且只有一个根结点、每个结点最多一个前件和一个后件”即线性结构——因此一般线性表、栈、队列、循环队列、单链表、双向链表、循环链表均属于线性结构！而与采用的存储结构（顺序还是链式）毫无关系！$kba24s_81$),
(82, $kba24b_82$[{"t":"list","id":"a2-2-4-3-b1","imp":"core","title":"","ordered":false,"items":["1、==顺序表的删除操作与栈的基本概念==：^^顺序表的删除操作^^：==在长度为 n 的顺序表中删除第 i 个元素==，需要将其后的 a(i+1) 至 a(n) 共 n−i 个元素依次前移一个位置。","① ^^最好的情况^^：==删除表尾元素（i = n）==，移动次数为 0。","② ^^最坏的情况^^：==删除第一个元素（i = 1），移动次数为 n−1。==","③ ^^平均情况^^：==假设在各个位置删除元素的机会相等==，平均移动次数为 (n−1)/2。","④ ==删除算法的主要时间花费在元素移动上==，平均时间复杂度为 O(n)。","2、==线性表的定义及顺序存储结构的插入与删除==：","^^1) 线性表的定义^^：线性表是具有相同数据类型的 n（n ≥ 0）个数据元素的有限序列。","2) 线性表的顺序存储结构及其插入与删除运算：顺序表的插入与删除其实都是查找和移动的过程，分为==按位置和按值两种==。 按位置比较简单：插入时从表尾开始到要插入的位置，每个元素向后移动一个位置，最后将待插入的值放入；删除时从要删除元素的后一个开始，所有元素向前移动一个位置即可。 按值删除需要先查找，可以选择顺序查找、二分查找（有序表）等，找到后记录位置，后续操作与按位置删除相同。","3、==线性表的特点及相关概念辨析==：线性表是由 n（n ≥ 0）个相同类型数据元素构成==的有限序列==，其特点是表中元素个数有限。 队列是一种特殊的线性表，只允许在表的一端插入、在另一端删除；允许插入的一端是队尾（rear），允许删除的一端是队头（front）。表中没有元素时为空队列，队列是一种先进先出（FIFO）的线性表。 瀑布模型本质上是一种线性顺序模型，按需求分析、设计、编码、测试、运行与维护的顺序依次推进。 软件结构图着重反映模块间的隶属关系，即模块间的调用关系和层次关系。","4、^^线性表的运算与操作^^：","① ==顺序表的运算==：^^查找、插入、删除、合并、排序、复制、逆转等^^；","② ==原则==：^^运算后仍保持线性表的特性^^；","③ ==示例==：^^略。^^"]},{"t":"callout","id":"a2-2-4-3-b4","imp":"core","kind":"tip","text":"数据结构四要素：==逻辑结构（面向用户，分为线性结构如表/栈/队列，非线性结构如树/图）、物理存储结构（面向内存，分为顺序存储、链式存储、索引存储与散列存储）==，以及在特定数据结构上定义的一组基本操作运算。","title":"考向复习提示：数据结构逻辑结构与物理存储结构"},{"t":"callout","id":"a2-2-4-3-b5","imp":"core","kind":"trap","text":"很多考生望文生义，看到“循环队列”中有“循环”、看到“双向链表”中有分支连接，就武断将其误归为非线性结构；专转本明确规定：==逻辑结构只取决于数据元素间的前驱后继关系，顺序表、单链表、双向链表、循环链表、栈、队列全部属于线性结构==！只有树（一对多）和图（多对多）才是非线性结构！","title":"高频易错陷阱：循环队列与双向链表属于线性结构！"}]$kba24b_82$::jsonb, $kba24s_82$A2-2.4.3 线性表的定义，线性表的顺序存储结构及其插入与删除运算。 1、顺序表的删除操作与栈的基本概念：顺序表的删除操作：在长度为 n 的顺序表中删除第 i 个元素，需要将其后的 a(i+1) 至 a(n) 共 n−i 个元素依次前移一个位置。 ① 最好的情况：删除表尾元素（i = n），移动次数为 0。 ② 最坏的情况：删除第一个元素（i = 1），移动次数为 n−1。 ③ 平均情况：假设在各个位置删除元素的机会相等，平均移动次数为 (n−1)/2。 ④ 删除算法的主要时间花费在元素移动上，平均时间复杂度为 O(n)。 2、线性表的定义及顺序存储结构的插入与删除： 1) 线性表的定义：线性表是具有相同数据类型的 n（n ≥ 0）个数据元素的有限序列。 2) 线性表的顺序存储结构及其插入与删除运算：顺序表的插入与删除其实都是查找和移动的过程，分为按位置和按值两种。 按位置比较简单：插入时从表尾开始到要插入的位置，每个元素向后移动一个位置，最后将待插入的值放入；删除时从要删除元素的后一个开始，所有元素向前移动一个位置即可。 按值删除需要先查找，可以选择顺序查找、二分查找（有序表）等，找到后记录位置，后续操作与按位置删除相同。 3、线性表的特点及相关概念辨析：线性表是由 n（n ≥ 0）个相同类型数据元素构成的有限序列，其特点是表中元素个数有限。 队列是一种特殊的线性表，只允许在表的一端插入、在另一端删除；允许插入的一端是队尾（rear），允许删除的一端是队头（front）。表中没有元素时为空队列，队列是一种先进先出（FIFO）的线性表。 瀑布模型本质上是一种线性顺序模型，按需求分析、设计、编码、测试、运行与维护的顺序依次推进。 软件结构图着重反映模块间的隶属关系，即模块间的调用关系和层次关系。 4、线性表的运算与操作： ① 顺序表的运算：查找、插入、删除、合并、排序、复制、逆转等； ② 原则：运算后仍保持线性表的特性； ③ 示例：略。 考向复习提示：数据结构逻辑结构与物理存储结构 数据结构四要素：逻辑结构（面向用户，分为线性结构如表/栈/队列，非线性结构如树/图）、物理存储结构（面向内存，分为顺序存储、链式存储、索引存储与散列存储），以及在特定数据结构上定义的一组基本操作运算。 高频易错陷阱：循环队列与双向链表属于线性结构！ 很多考生望文生义，看到“循环队列”中有“循环”、看到“双向链表”中有分支连接，就武断将其误归为非线性结构；专转本明确规定：逻辑结构只取决于数据元素间的前驱后继关系，顺序表、单链表、双向链表、循环链表、栈、队列全部属于线性结构！只有树（一对多）和图（多对多）才是非线性结构！$kba24s_82$),
(83, $kba24b_83$[{"t":"list","id":"a2-2-4-4-b7","imp":"core","items":["1、线性表及其顺序存储结构","（1）^^线性表：^^==由一组数据元素构成，数据元素的位置只取决于自己的序号，元素之间的相对位置是线性的。==","（2）^^在复杂线性表中，由若干项数据元素组成的数据元素称为记录；由多个记录构成的线性表称为文件。^^","（3）非空线性表的结构特征：","==①、有且只有一个根结点a1，它无前件==","==②、有且只有一个终端结点an，它无后件；==","==③、除根结点与终端结点外，其他所有结点有且只有一个前件，也有且只有一个后件。==","（4）结点个数n 称为线性表的长度，当n=0 时，称为空表","（5）^^线性表的^^==顺序存储结构==^^具有以下两个基本特点：^^","==①、线性表中所有元素所占的存储空间是连续的；==","==②、线性表中各数据元素在存储空间中是按逻辑顺序依次存放的。==","（6）^^线性表存储结构实现的举例：^^","^^①、^^==数组==^^：有序存储，占有一片连继地址，顺序存储结构的。^^","^^②、^^==链表==^^：无序存放的元素关联起来，链式存储结构的。^^","^^③、^^==栈==^^：先进先出(限定在一端)，链式结构或顺序存储结构。^^","（7）线性表的运算与操作","①、顺序表的运算：查找、插入、删除、合并、排序、复制、逆转等","②、原则：运算后仍操持线性表的特性","③、示例："],"title":"","ordered":false},{"h":429,"t":"img","w":1157,"id":"a2-2-4-4-b8","imp":"normal","src":"/kb-assets/theory/p40_r0_3d57705dccf845a5.png","title":""},{"t":"list","id":"a2-2-4-4-b9","imp":"core","items":["2、==栈==","==（1）栈是一种特殊的线性表，只允许在表的一端进行插入和删除的线性表；插入，删除的一端为栈顶，另一端为栈底；当表中没有元素时为空栈。==","==（2）栈是一种==@@后进先出@@==（或先进后出Last In First Out）的线性表。栈具有记忆功能。==","（3）^^栈的存储结构：^^","^^①、顺序存储结构：用一组地址连续的存储单元即一维数组来存储；^^","^^②、链式存储：用线性链表来存储；^^","（4）栈的基本运算","①、==入栈运算==，在栈顶位置插入元素；","②、==退栈运==算，删除元素(取出栈顶元素并赋给一个指定的变量)；","③、==读栈顶元素==，将栈顶元素赋给一个指定的变量，此时指针无变化。","（5）运算举例："],"title":"","ordered":false},{"h":424,"t":"img","w":1151,"id":"a2-2-4-4-b10","imp":"normal","src":"/kb-assets/theory/p40_r1_4288e41078983052.png","title":""},{"t":"list","id":"a2-2-4-4-b11","imp":"core","items":["top=0，表示栈空，top=m 表示栈满","3、==队列==","（1）==队列是一种特殊的线性表，只允许在表的一端插入，在另一端删除，允许插入的一端是队尾（rear），允许删除的一端为队头（front）；当表中没有元素是空队列；队列是一种==@@先进先出@@==的线性表。(FIFO)==","（2）^^队列的存储结构：^^","^^①、顺序存储结构：一维数组^^","^^②、链式存储：线性链表；^^","（3）==队列的顺序存储结构一般采用循环队列的形式==。循环队列s=0 表示队列为空；s=1 且front=rear 表示队满。","（4）队列的基本运算","==①、入队运算：从队尾插入一个元素；==","==②、退队运算：从队头删除一个元素==","==③、取读队头元素==","（5）计算循环队列的元素个数：“尾指针减头指针”，若为负数，再加其容量即可。","==队列长度（元素个数）=（m+rear-front)%m==m 为总长度。"],"title":"","ordered":false},{"h":292,"t":"img","w":325,"id":"a2-2-4-4-b12","imp":"normal","src":"/kb-assets/theory/p41_r0_8357e9dc08937efd.png","title":""},{"t":"list","id":"a2-2-4-4-b13","imp":"normal","items":["（6）运行举例："],"title":"","ordered":false},{"h":295,"t":"img","w":676,"id":"a2-2-4-4-b14","imp":"normal","src":"/kb-assets/theory/p41_r1_bdf774f2833554cf.png","title":""},{"t":"list","id":"a2-2-4-4-b15","imp":"core","items":["4、^^线性链表^^","（1）^^线性链表是线性表的链式存储结构，数据结构中的每一个结点对应于一个存储单元，这种存储单元称为存储结点，简称结点。^^结点由两部分组成：","①、用于存储数据元素值，称为==数据域==；","②、用于存放指针，称为==指针域==，用于指向前一个或后一个结点。","（2）在链式存储结构中，存储数据结构的==存储空间可以不连续==，各数据结点的存储顺序与数据元素之间的逻辑关系可以不一致，而数据元素之间的逻辑关系是由指针域来确定的。链式存储方式既可以用于表示线性结构，也可用于表示非线性结构。","5、==数据结构化==：^^数据结构化^^：==数据库系统中的数据面向整个单位的全局应用==，采用一定的数据模型（关系模型）进行描述和定义，因而数据具有整体结构化的特征。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-4-4-b16","imp":"core","kind":"tip","text":"• ==顺序表（数组）==：占用连续内存，==支持 O(1) 随机存取==；但插入和删除需成批移动数据，时间复杂度为 O(n)，且容量静态固定； • ==链表（单链表）==：内存节点离散分布，通过指针串联，==插入和删除只需修改指针指针 O(1)==；但不支持随机存取（查找为 O(n)），且需要指针域额外开销。","title":"考向复习提示：顺序表 vs 链表的核心性能对比"},{"t":"callout","id":"a2-2-4-4-b17","imp":"core","kind":"trap","text":"单链表在节点 p 后插入节点 s：==必须先将 s 的后继指针指向 p 的后继，再将 p 的后继指向 s==（即 `s->next = p->next; p->next = s;`）；若将两句顺序颠倒，会导致原链表后续节点地址彻底丢失（内存泄露断链）！","title":"高频易错陷阱：链表节点的插入与删除指针修改顺序"}]$kba24b_83$::jsonb, $kba24s_83$A2-2.4.4 栈和队列的定义，栈和队列的顺序存储结构及其基本运算。 1、线性表及其顺序存储结构 （1）线性表：由一组数据元素构成，数据元素的位置只取决于自己的序号，元素之间的相对位置是线性的。 （2）在复杂线性表中，由若干项数据元素组成的数据元素称为记录；由多个记录构成的线性表称为文件。 （3）非空线性表的结构特征： ①、有且只有一个根结点a1，它无前件 ②、有且只有一个终端结点an，它无后件； ③、除根结点与终端结点外，其他所有结点有且只有一个前件，也有且只有一个后件。 （4）结点个数n 称为线性表的长度，当n=0 时，称为空表 （5）线性表的顺序存储结构具有以下两个基本特点： ①、线性表中所有元素所占的存储空间是连续的； ②、线性表中各数据元素在存储空间中是按逻辑顺序依次存放的。 （6）线性表存储结构实现的举例： ①、数组：有序存储，占有一片连继地址，顺序存储结构的。 ②、链表：无序存放的元素关联起来，链式存储结构的。 ③、栈：先进先出(限定在一端)，链式结构或顺序存储结构。 （7）线性表的运算与操作 ①、顺序表的运算：查找、插入、删除、合并、排序、复制、逆转等 ②、原则：运算后仍操持线性表的特性 ③、示例： 2、栈 （1）栈是一种特殊的线性表，只允许在表的一端进行插入和删除的线性表；插入，删除的一端为栈顶，另一端为栈底；当表中没有元素时为空栈。 （2）栈是一种后进先出（或先进后出Last In First Out）的线性表。栈具有记忆功能。 （3）栈的存储结构： ①、顺序存储结构：用一组地址连续的存储单元即一维数组来存储； ②、链式存储：用线性链表来存储； （4）栈的基本运算 ①、入栈运算，在栈顶位置插入元素； ②、退栈运算，删除元素(取出栈顶元素并赋给一个指定的变量)； ③、读栈顶元素，将栈顶元素赋给一个指定的变量，此时指针无变化。 （5）运算举例： top=0，表示栈空，top=m 表示栈满 3、队列 （1）队列是一种特殊的线性表，只允许在表的一端插入，在另一端删除，允许插入的一端是队尾（rear），允许删除的一端为队头（front）；当表中没有元素是空队列；队列是一种先进先出的线性表。(FIFO) （2）队列的存储结构： ①、顺序存储结构：一维数组 ②、链式存储：线性链表； （3）队列的顺序存储结构一般采用循环队列的形式。循环队列s=0 表示队列为空；s=1 且front=rear 表示队满。 （4）队列的基本运算 ①、入队运算：从队尾插入一个元素； ②、退队运算：从队头删除一个元素 ③、取读队头元素 （5）计算循环队列的元素个数：“尾指针减头指针”，若为负数，再加其容量即可。 队列长度（元素个数）=（m+rear-front)%mm 为总长度。 （6）运行举例： 4、线性链表 （1）线性链表是线性表的链式存储结构，数据结构中的每一个结点对应于一个存储单元，这种存储单元称为存储结点，简称结点。结点由两部分组成： ①、用于存储数据元素值，称为数据域； ②、用于存放指针，称为指针域，用于指向前一个或后一个结点。 （2）在链式存储结构中，存储数据结构的存储空间可以不连续，各数据结点的存储顺序与数据元素之间的逻辑关系可以不一致，而数据元素之间的逻辑关系是由指针域来确定的。链式存储方式既可以用于表示线性结构，也可用于表示非线性结构。 5、数据结构化：数据结构化：数据库系统中的数据面向整个单位的全局应用，采用一定的数据模型（关系模型）进行描述和定义，因而数据具有整体结构化的特征。 考向复习提示：顺序表 vs 链表的核心性能对比 • 顺序表（数组）：占用连续内存，支持 O(1) 随机存取；但插入和删除需成批移动数据，时间复杂度为 O(n)，且容量静态固定； • 链表（单链表）：内存节点离散分布，通过指针串联，插入和删除只需修改指针指针 O(1)；但不支持随机存取（查找为 O(n)），且需要指针域额外开销。 高频易错陷阱：链表节点的插入与删除指针修改顺序 单链表在节点 p 后插入节点 s：必须先将 s 的后继指针指向 p 的后继，再将 p 的后继指向 s（即 `s->next = p->next; p->next = s;`）；若将两句顺序颠倒，会导致原链表后续节点地址彻底丢失（内存泄露断链）！$kba24s_83$);
do $$
declare r record; old_rev record; v_rev integer; n integer;
begin
  select count(*) into n from _kba24;
  if n <> 4 then raise exception '预期 4 个节点，实际 %', n; end if;
  for r in select node_id, blocks, search_text from _kba24 order by node_id loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
